          },
        },
      });

      // Menginisialisasi grafik sinyal input
      const inputCtx = inputSignal.value.getContext("2d");
      inputSignalChart = new Chart(inputCtx, {
        type: "line",
        data: {
          labels: [],
          datasets: [
            {
              label: "Sinyal Input",
              data: [],
