                color: "#e0e0e0",
                font: {
                  size: 12,
                },
                callback: function (value) {
                  return value.toFixed(4);
                },
              },
              suggestedMin: -1,
              suggestedMax: 1,
            },
          },
        },
      });

      // Perhitungan awal
      calculateParameters();
    };

    onMounted(() => {
      initializeCharts();
      // Menginisialisasi tooltip
      tippy("[data-tippy-content]", {
        animation: "scale",
        duration: 200,
      });
    });

    // Membersihkan frame animasi saat komponen di-unmount
    onUnmounted(() => {
      if (animationFrameId) {
        if (typeof animationFrameId === "number") {
          cancelAnimationFrame(animationFrameId);
        } else {
          clearTimeout(animationFrameId);
        }
      }
    });

    return {
      vin,
      c1,
      c2,
      r1,
      r2,
      r3,
      r4,
      signalFreq,
      signalAmp,
      cutOffFreq,
      vout,
      gain,
      gainDB,
      frequencyResponse,
      inputSignal,
      outputSignal,
      Q,
    };
  },
};
</script>

